-- Add the locked starter estimate template "Wastewater plant civil package (illustrative)" and the illustrative catalogue items it prices from, to ONE workspace.
-- Run by hand in the SQL editor of the database that holds the workspace. Needs supabase/migrations/0131_estimator.sql and
-- 0213_estimate_template_catalogue.sql; the catalogue items need 0098 (products) and are skipped without it.
--
-- WHICH WORKSPACE: change the one line marked CHANGE THIS (v_slug) and nothing else. The script stops, changing nothing, when
--   - no workspace has that slug,
--   - the workspace is flagged as a demo workspace (those get scripts/run-bundle-57-starter-wastewater-civil-2026-11-26.sql instead),
--   - the workspace does not have the Estimates module on (features.estimator): switch it on in /admin/tenants first.
--
-- ADD ONLY, never overwrite: the template is added when the workspace has none of that name, and an existing one is left exactly as it
-- is. Each of the 17 catalogue items is added only when the workspace has no product with that SKU, so an item that was edited,
-- renamed or repriced from a rate sheet is never touched. Items are marked illustrative (name suffix, custom_data.illustrative, no cost date)
-- until a rate sheet replaces the cost. Safe to run again. Needs no other script first.
-- GENERATED by scripts/gen-estimate-seeds.ts from src/lib/estimator/starterTemplatesWastewater.ts; do not edit by hand, change that
-- file and regenerate.

do $seed$
declare
  v_slug text := 'kamco'; -- CHANGE THIS: the slug of the workspace
  t uuid;
  v_demo boolean;
  v_est boolean;
  seq int;
  item record;
begin
  if not exists (select 1 from information_schema.columns where table_name = 'estimate_templates' and column_name = 'locked') then
    raise exception 'Run supabase/migrations/0213_estimate_template_catalogue.sql first (estimate_templates.locked is missing).';
  end if;
  if to_regclass('public.estimate_templates') is null then
    raise exception 'Run supabase/migrations/0131_estimator.sql first.';
  end if;

  select id, coalesce(is_demo, false), coalesce((features->>'estimator')::boolean, false) into t, v_demo, v_est from tenants where slug = v_slug;
  if t is null then
    raise exception 'No workspace with slug % was found. Nothing was changed. Check the slug in the tenants table.', v_slug;
  end if;
  if v_demo then
    raise exception 'The workspace % is flagged as a demo workspace. Run scripts/run-bundle-57-starter-wastewater-civil-2026-11-26.sql for demo workspaces. Nothing was changed.', v_slug;
  end if;
  if not v_est then
    raise exception 'The workspace % does not have the Estimates module on (features.estimator). Switch it on in /admin/tenants, then run this again. Nothing was changed.', v_slug;
  end if;

  if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Wastewater plant civil package (illustrative)')) then
    insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules, keywords, icon, locked, customer_visible)
    values (
      t, 'Wastewater plant civil package (illustrative)', 'ILLUSTRATIVE starter for the civil works of an industrial wastewater treatment and recycling plant: earthworks and soil replacement, tank and foundation concrete, waterproofing, geotextile, HDPE membrane works, and water-tightness and seam testing. Materials come from catalogue items marked illustrative until you import a rate sheet; plant, labour and test rates are placeholders. Blockwork and plaster are left to their own starter.', 'civil', '', 1, true, 'group',
      $inputs$[{"key":"exc_m3","label":"Volume to excavate","type":"number","default":8000,"min":0,"max":10000000,"unit":"m³","section":"Earthworks"},{"key":"soil_type","label":"Soil","type":"select","default":"sand","options":[{"key":"sand","label":"Sand or loose soil","value":1},{"key":"clay","label":"Stiff clay","value":1.4},{"key":"rock","label":"Rock","value":2.5}],"help":"Clay digs slower than sand, and rock needs a breaker as well as the excavator.","section":"Earthworks"},{"key":"repl_area_m2","label":"Poor soil to replace, plan area","type":"number","default":2500,"min":0,"max":1000000,"unit":"m²","help":"The area where soft or unsuitable soil is dug out below the structures and replaced. Taken as soft soil, never rock.","section":"Soil replacement and fill"},{"key":"repl_depth_m","label":"Replacement depth","type":"number","default":1,"min":0,"max":6,"unit":"m","section":"Soil replacement and fill"},{"key":"repl_fill","label":"Replacement fill","type":"select","default":"selected","options":[{"key":"selected","label":"Selected granular fill","value":1},{"key":"crushed","label":"Crushed rock base","value":2}],"section":"Soil replacement and fill"},{"key":"backfill_m3","label":"Excavated soil put back (compacted)","type":"number","default":4500,"min":0,"max":10000000,"unit":"m³","help":"The excavated soil that is reused. What is not put back is carted away.","section":"Soil replacement and fill"},{"key":"import_fill_m3","label":"Imported fill for backfill","type":"number","default":1200,"min":0,"max":10000000,"unit":"m³","section":"Soil replacement and fill"},{"key":"dump_km","label":"Distance to the tip","type":"number","default":20,"min":0,"max":500,"unit":"km","section":"Soil replacement and fill"},{"key":"concrete_m3","label":"Concrete in foundations, tanks, channels and sumps","type":"number","default":1800,"min":0,"max":10000000,"unit":"m³","section":"Concrete structures"},{"key":"concrete_grade","label":"Grade","type":"select","default":"c35","options":[{"key":"c25","label":"C25","value":25,"attrs":{"concrete_grade":"c25"}},{"key":"c30","label":"C30","value":30,"attrs":{"concrete_grade":"c30"}},{"key":"c35","label":"C35","value":35,"attrs":{"concrete_grade":"c35"}},{"key":"c40","label":"C40","value":40,"attrs":{"concrete_grade":"c40"}},{"key":"c50","label":"C50","value":50,"attrs":{"concrete_grade":"c50"}}],"section":"Concrete structures"},{"key":"pumped","label":"Placed by pump","type":"boolean","default":true,"section":"Concrete structures"},{"key":"rebar_kg_m3","label":"Reinforcement","type":"number","default":130,"min":0,"max":500,"unit":"kg per m³","section":"Concrete structures"},{"key":"formwork_m2_per_m3","label":"Formwork contact area","type":"number","default":7,"min":0,"max":40,"unit":"m² per m³","help":"About 2 for a thick slab, 6 for a slab or beam, 10 or more for walls.","section":"Concrete structures"},{"key":"blinding_m2","label":"Blinding, plan area","type":"number","default":2500,"min":0,"max":1000000,"unit":"m²","section":"Concrete structures"},{"key":"blinding_thk_mm","label":"Blinding thickness","type":"number","default":100,"min":50,"max":300,"unit":"mm","section":"Concrete structures"},{"key":"wp_area_m2","label":"Waterproofed area","type":"number","default":4500,"min":0,"max":1000000,"unit":"m²","section":"Waterproofing"},{"key":"wp_system","label":"System","type":"select","default":"sheet","options":[{"key":"cementitious","label":"Cementitious coating","value":1,"attrs":{"wp_system":"cementitious"}},{"key":"sheet","label":"Bituminous sheet membrane","value":2,"attrs":{"wp_system":"sheet"}},{"key":"pu","label":"Polyurethane liquid membrane","value":3,"attrs":{"wp_system":"pu"}}],"help":"Picks the waterproofing material from your catalogue. A membrane also takes primer.","section":"Waterproofing"},{"key":"wp_protect","label":"Protection board over the membrane","type":"boolean","default":true,"section":"Waterproofing"},{"key":"gt_area_m2","label":"Geotextile area","type":"number","default":6000,"min":0,"max":1000000,"unit":"m²","section":"Geotextile"},{"key":"gt_overlap_pct","label":"Overlap","type":"number","default":10,"min":0,"max":50,"unit":"%","section":"Geotextile"},{"key":"hdpe_area_m2","label":"Liner area","type":"number","default":4000,"min":0,"max":1000000,"unit":"m²","section":"HDPE membrane"},{"key":"hdpe_thk","label":"Thickness","type":"select","default":"t20","options":[{"key":"t15","label":"1.5 mm","value":1.5,"attrs":{"hdpe_thk":"1.5"}},{"key":"t20","label":"2.0 mm","value":2,"attrs":{"hdpe_thk":"2.0"}}],"section":"HDPE membrane"},{"key":"hdpe_waste_pct","label":"Wastage (cut-offs and trimming)","type":"number","default":8,"min":0,"max":30,"unit":"%","section":"HDPE membrane"},{"key":"hdpe_detail_m","label":"Extrusion-welded details (pipe boots, corners, patches)","type":"number","default":200,"min":0,"max":1000000,"unit":"m","section":"HDPE membrane"},{"key":"tanks_n","label":"Tanks to test","type":"number","default":8,"min":0,"max":1000,"unit":"nr","section":"Testing"},{"key":"test_m3","label":"Test water per tank","type":"number","default":650,"min":1,"max":1000000,"unit":"m³","section":"Testing"},{"key":"test_hold_days","label":"Hold time","type":"number","default":7,"min":1,"max":60,"unit":"days","section":"Testing"}]$inputs$::jsonb,
      $rates$[{"key":"exc_m3_per_h","label":"Excavator production in sand","unit":"m³/h","value":25},{"key":"excavator_rate_hr","label":"Excavator with operator","unit":"per h","value":145,"low":130,"high":175},{"key":"breaker_h_per_m3","label":"Breaker time in rock","unit":"h/m³","value":0.15},{"key":"breaker_rate_hr","label":"Hydraulic breaker with operator","unit":"per h","value":190,"low":170,"high":230},{"key":"backfill_cost_m3","label":"Backfill and compaction, labour and plant","unit":"per m³","value":18,"low":15,"high":24},{"key":"fill_waste_pct","label":"Wastage on imported fill","unit":"%","value":5},{"key":"spoil_swell","label":"Loose volume of spoil per m³ in place","unit":"factor","value":1.25},{"key":"cart_cost_m3_km","label":"Spoil carted, per m³ and km","unit":"per m³-km","value":0.45,"low":0.38,"high":0.6},{"key":"tipping_fee_m3","label":"Tipping fee","unit":"per m³","value":6},{"key":"concrete_waste_pct","label":"Wastage on concrete","unit":"%","value":3},{"key":"rebar_waste_pct","label":"Wastage on reinforcement","unit":"%","value":5},{"key":"form_h_per_m2","label":"Carpenter hours to fix and strip a m² of formwork","unit":"h/m²","value":0.9,"low":0.75,"high":1.2},{"key":"rebar_h_per_kg","label":"Steel fixer hours per kg","unit":"h/kg","value":0.012,"low":0.01,"high":0.016},{"key":"place_h_per_m3","label":"Placing, vibrating and curing hours per m³","unit":"h/m³","value":1.2},{"key":"labour_rate_hr","label":"Labour rate","unit":"per h","value":16,"low":14,"high":20},{"key":"pump_m3_per_h","label":"Pump output","unit":"m³/h","value":30},{"key":"pump_rate_hr","label":"Concrete pump with operator","unit":"per h","value":210,"low":190,"high":260},{"key":"wp_waste_pct","label":"Laps, upstands and wastage on waterproofing","unit":"%","value":8},{"key":"wp_primer_l_per_m2","label":"Primer per m² of membrane","unit":"l/m²","value":0.25},{"key":"wp_h_cem","label":"Labour per m² of cementitious coating","unit":"h/m²","value":0.18,"low":0.15,"high":0.25},{"key":"wp_h_sheet","label":"Labour per m² of sheet membrane","unit":"h/m²","value":0.3,"low":0.25,"high":0.4},{"key":"wp_h_pu","label":"Labour per m² of liquid membrane","unit":"h/m²","value":0.25,"low":0.2,"high":0.35},{"key":"wp_board_h_per_m2","label":"Labour per m² of protection board","unit":"h/m²","value":0.06},{"key":"gt_waste_pct","label":"Wastage on geotextile","unit":"%","value":3},{"key":"gt_h_per_m2","label":"Labour per m² of geotextile laid","unit":"h/m²","value":0.03},{"key":"hdpe_roll_w_m","label":"Liner roll width (a seam runs along each roll)","unit":"m","value":8},{"key":"hdpe_crew_rate_hr","label":"Liner crew, per hour","unit":"per h","value":24,"low":20,"high":32},{"key":"hdpe_deploy_h_per_m2","label":"Crew hours to deploy a m² of liner","unit":"h/m²","value":0.12,"low":0.1,"high":0.16},{"key":"hdpe_weld_rate_m","label":"Fusion welding (crew and machine), per m of seam","unit":"per m","value":9,"low":7,"high":13},{"key":"hdpe_ext_rate_m","label":"Extrusion welding, per m of detail","unit":"per m","value":22,"low":17,"high":30},{"key":"hdpe_seam_test_h_per_m","label":"Seam test crew hours per m of fusion seam","unit":"h/m","value":0.02},{"key":"test_reuse_share","label":"Share of test water reused from tank to tank","unit":"fraction","value":0.6},{"key":"test_water_cost_m3","label":"Test water, delivered","unit":"per m³","value":9,"low":6,"high":14},{"key":"test_pump_m3_per_h","label":"Test pump output","unit":"m³/h","value":130},{"key":"test_pump_rate_hr","label":"Test pump with operator","unit":"per h","value":55,"low":45,"high":70},{"key":"test_setup_h","label":"Labour hours to fill, fit gauges and drain one tank","unit":"h","value":16},{"key":"test_monitor_h_per_day","label":"Technician hours per tank per day of the hold","unit":"h/day","value":3},{"key":"tech_rate_hr","label":"Technician rate","unit":"per h","value":24,"low":20,"high":30},{"key":"vac_test_rate_m","label":"Vacuum and spark testing, per m of weld","unit":"per m","value":7,"low":5,"high":10},{"key":"overhead_factor","label":"Overhead (share of all the cost above)","unit":"fraction","value":0.1}]$rates$::jsonb,
      $rules$[{"code":"exc","group":"31 23 16 Excavation","description":"Excavation (excavator with operator)","uom":"h","qty":"exc_m3 * soil_type / exc_m3_per_h","component":"other","cost":{"kind":"rate","rate":"excavator_rate_hr"}},{"code":"rock","group":"31 23 16 Excavation","description":"Rock breaking (hydraulic breaker)","uom":"h","qty":"(soil_type > 2) * exc_m3 * breaker_h_per_m3","component":"other","cost":{"kind":"rate","rate":"breaker_rate_hr"}},{"code":"pdig","group":"31 23 16 Excavation","description":"Poor soil dug out below structures (excavator with operator)","uom":"h","qty":"(repl_area_m2 * repl_depth_m) / exc_m3_per_h","component":"other","cost":{"kind":"rate","rate":"excavator_rate_hr"}},{"code":"rfs","group":"31 23 23 Soil replacement and fill","description":"Replacement fill: selected granular fill","uom":"m3","qty":"(repl_fill == 1) * (repl_area_m2 * repl_depth_m)","waste_pct":"fill_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-FILL"}},{"code":"rfc","group":"31 23 23 Soil replacement and fill","description":"Replacement fill: crushed rock base","uom":"m3","qty":"(repl_fill == 2) * (repl_area_m2 * repl_depth_m)","waste_pct":"fill_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-WW-CRUSHED"}},{"code":"rcp","group":"31 23 23 Soil replacement and fill","description":"Placing and compacting replacement fill (labour and plant)","uom":"m3","qty":"(repl_area_m2 * repl_depth_m)","component":"other","cost":{"kind":"rate","rate":"backfill_cost_m3"}},{"code":"bkf","group":"31 23 23 Soil replacement and fill","description":"Backfill and compaction (labour and plant)","uom":"m3","qty":"backfill_m3","component":"other","cost":{"kind":"rate","rate":"backfill_cost_m3"}},{"code":"fill","group":"31 23 23 Soil replacement and fill","description":"Imported selected fill for backfill","uom":"m3","qty":"import_fill_m3","waste_pct":"fill_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-FILL"}},{"code":"cart","group":"Disposal of surplus","description":"Surplus spoil carted to tip","uom":"m3-km","qty":"max(0, exc_m3 + (repl_area_m2 * repl_depth_m) - backfill_m3) * spoil_swell * dump_km","component":"transport","cost":{"kind":"rate","rate":"cart_cost_m3_km"}},{"code":"tip","group":"Disposal of surplus","description":"Tipping fee","uom":"m3","qty":"max(0, exc_m3 + (repl_area_m2 * repl_depth_m) - backfill_m3) * spoil_swell","component":"other","cost":{"kind":"rate","rate":"tipping_fee_m3"}},{"code":"bld","group":"Blinding concrete","description":"Blinding concrete C25, delivered","uom":"m3","qty":"blinding_m2 * blinding_thk_mm / 1000","waste_pct":"concrete_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-RMX-C25"}},{"code":"blp","group":"Blinding concrete","description":"Placing and levelling blinding (labour)","uom":"h","qty":"qty_bld * place_h_per_m3","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"fwm","group":"03 11 00 Concrete forming and accessories","description":"Formwork materials","uom":"m2","qty":"concrete_m3 * formwork_m2_per_m3","component":"materials","cost":{"kind":"product","sku":"EST-FORMWORK"}},{"code":"fwl","group":"03 11 00 Concrete forming and accessories","description":"Formwork labour (fix and strip)","uom":"h","qty":"qty_fwm * form_h_per_m2","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"rbr","group":"03 21 00 Reinforcing steel","description":"Reinforcement steel (cut and bent)","uom":"kg","qty":"concrete_m3 * rebar_kg_m3","waste_pct":"rebar_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-REBAR"}},{"code":"rbl","group":"03 21 00 Reinforcing steel","description":"Reinforcement labour (cut, bend and fix)","uom":"h","qty":"qty_rbr * rebar_h_per_kg","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"conc","group":"03 30 00 Cast-in-place concrete","description":"Ready-mix concrete, delivered","uom":"m3","qty":"concrete_m3","waste_pct":"concrete_waste_pct","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"ready_mix"},"from":["concrete_grade"]}}},{"code":"plc","group":"03 30 00 Cast-in-place concrete","description":"Placing, vibrating and curing labour","uom":"h","qty":"concrete_m3 * place_h_per_m3","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"pmp","group":"03 30 00 Cast-in-place concrete","description":"Concrete pump","uom":"h","qty":"pumped * concrete_m3 / pump_m3_per_h","component":"other","cost":{"kind":"rate","rate":"pump_rate_hr"}},{"code":"wpm","group":"Waterproofing","description":"Waterproofing system, supplied","uom":"m2","qty":"wp_area_m2","waste_pct":"wp_waste_pct","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"waterproofing"},"from":["wp_system"]}}},{"code":"wpp","group":"Waterproofing","description":"Primer (membrane systems)","uom":"l","qty":"(wp_system > 1) * wp_area_m2 * wp_primer_l_per_m2","waste_pct":"wp_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-WP-PRIMER"}},{"code":"wpb","group":"Waterproofing","description":"Protection board","uom":"m2","qty":"wp_protect * wp_area_m2","waste_pct":"wp_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-WP-BOARD"}},{"code":"wpl","group":"Waterproofing","description":"Waterproofing application labour","uom":"h","qty":"wp_area_m2 * if(wp_system == 1, wp_h_cem, if(wp_system == 2, wp_h_sheet, wp_h_pu))","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"wpf","group":"Waterproofing","description":"Protection board fixing labour","uom":"h","qty":"qty_wpb * wp_board_h_per_m2","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"gtm","group":"Geotextile","description":"Geotextile, including overlaps","uom":"m2","qty":"gt_area_m2 * (1 + gt_overlap_pct / 100)","waste_pct":"gt_waste_pct","component":"materials","cost":{"kind":"product","sku":"EST-GEOTEXTILE"}},{"code":"gtl","group":"Geotextile","description":"Geotextile laying labour","uom":"h","qty":"qty_gtm * gt_h_per_m2","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"lin","group":"HDPE membrane works","description":"HDPE geomembrane liner, supplied","uom":"m2","qty":"hdpe_area_m2","waste_pct":"hdpe_waste_pct","component":"materials","cost":{"kind":"product","match":{"attrs":{"est_kind":"hdpe_liner"},"from":["hdpe_thk"]}}},{"code":"dep","group":"HDPE membrane works","description":"Liner deployment (crew)","uom":"h","qty":"hdpe_area_m2 * hdpe_deploy_h_per_m2","component":"labour","cost":{"kind":"rate","rate":"hdpe_crew_rate_hr"}},{"code":"seam","group":"HDPE membrane works","description":"Fusion welding of seams (length from the liner area)","uom":"m","qty":"(hdpe_area_m2 / hdpe_roll_w_m)","component":"other","cost":{"kind":"rate","rate":"hdpe_weld_rate_m"}},{"code":"ext","group":"HDPE membrane works","description":"Extrusion welding of details","uom":"m","qty":"hdpe_detail_m","component":"other","cost":{"kind":"rate","rate":"hdpe_ext_rate_m"}},{"code":"stl","group":"HDPE membrane works","description":"Seam test labour (air-channel test of fusion seams)","uom":"h","qty":"qty_seam * hdpe_seam_test_h_per_m","component":"labour","cost":{"kind":"rate","rate":"hdpe_crew_rate_hr"}},{"code":"tw","group":"Testing","description":"Water-tightness test: test water","uom":"m3","qty":"tanks_n * test_m3 * (1 - test_reuse_share)","component":"other","cost":{"kind":"rate","rate":"test_water_cost_m3"}},{"code":"tp","group":"Testing","description":"Water-tightness test: pumping","uom":"h","qty":"tanks_n * test_m3 / test_pump_m3_per_h","component":"other","cost":{"kind":"rate","rate":"test_pump_rate_hr"}},{"code":"ts","group":"Testing","description":"Water-tightness test: fill, gauges and drain (labour)","uom":"h","qty":"tanks_n * test_setup_h","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"tm","group":"Testing","description":"Water-tightness test: level monitoring over the hold (technician)","uom":"h","qty":"tanks_n * test_hold_days * test_monitor_h_per_day","component":"labour","cost":{"kind":"rate","rate":"tech_rate_hr"}},{"code":"vt","group":"Testing","description":"Vacuum and spark testing of extrusion welds","uom":"m","qty":"hdpe_detail_m","component":"other","cost":{"kind":"rate","rate":"vac_test_rate_m"}},{"code":"ovh","group":"Overhead","description":"Overhead","uom":"cost","qty":"sub_31_23_16_excavation + sub_31_23_23_soil_replacement_and_fill + sub_disposal_of_surplus + sub_blinding_concrete + sub_03_11_00_concrete_forming_and_accessories + sub_03_21_00_reinforcing_steel + sub_03_30_00_cast_in_place_concrete + sub_waterproofing + sub_geotextile + sub_hdpe_membrane_works + sub_testing","component":"overhead","cost":{"kind":"rate","rate":"overhead_factor"}}]$rules$::jsonb,
      array['wastewater', 'waste water', 'sewage', 'effluent', 'treatment plant', 'STP', 'ETP', 'WWTP', 'recycling plant', 'tank', 'tanks', 'sump', 'channel', 'water retaining', 'waterproofing', 'membrane', 'geotextile', 'HDPE', 'liner', 'geomembrane', 'water tightness', 'flood test', 'leak test', 'soil replacement', 'excavation', 'reinforced concrete', 'civil package', 'foundation']::text[], 'grid', true, false
    );
  end if;

  -- Catalogue items for the starters (17). Needs the products table (migration 0098); skipped without it.
  if to_regclass('public.products') is not null then
    select coalesce(max(nullif(regexp_replace(ref, '\D', '', 'g'), '')::int), 0) into seq from products where tenant_id = t and ref ~ '^PRD-\d+$';
    for item in select * from jsonb_to_recordset($items$[{"sku":"EST-FILL","name":"Selected fill, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":48,"custom_data":{"est_kind":"fill","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-REBAR","name":"Reinforcement steel, cut and bent (illustrative)","uom":"kg","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":3.2,"custom_data":{"est_kind":"rebar","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-FORMWORK","name":"Formwork materials (plywood, props, ties), per m² of contact area (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":22,"custom_data":{"est_kind":"formwork","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-RMX-C25","name":"Ready-mix concrete C25, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":255,"custom_data":{"est_kind":"ready_mix","concrete_grade":"c25","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-RMX-C30","name":"Ready-mix concrete C30, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":275,"custom_data":{"est_kind":"ready_mix","concrete_grade":"c30","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-RMX-C35","name":"Ready-mix concrete C35, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":295,"custom_data":{"est_kind":"ready_mix","concrete_grade":"c35","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-RMX-C40","name":"Ready-mix concrete C40, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":315,"custom_data":{"est_kind":"ready_mix","concrete_grade":"c40","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-RMX-C50","name":"Ready-mix concrete C50, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":345,"custom_data":{"est_kind":"ready_mix","concrete_grade":"c50","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-WW-CRUSHED","name":"Crushed rock base, delivered (illustrative)","uom":"m3","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":85,"custom_data":{"est_kind":"crushed_rock","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-WP-CEM","name":"Cementitious waterproofing coating, two coats (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":36,"custom_data":{"est_kind":"waterproofing","wp_system":"cementitious","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-WP-SHEET","name":"Bituminous sheet waterproofing membrane (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":58,"custom_data":{"est_kind":"waterproofing","wp_system":"sheet","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-WP-PU","name":"Polyurethane liquid waterproofing membrane (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":74,"custom_data":{"est_kind":"waterproofing","wp_system":"pu","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-WP-PRIMER","name":"Waterproofing primer (illustrative)","uom":"l","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":16,"custom_data":{"est_kind":"wp_primer","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-WP-BOARD","name":"Protection board over waterproofing (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":26,"custom_data":{"est_kind":"wp_protection","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-GEOTEXTILE","name":"Nonwoven geotextile, 300 g/m2 (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":7.5,"custom_data":{"est_kind":"geotextile","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-HDPE-15","name":"HDPE geomembrane 1.5 mm, smooth (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":21,"custom_data":{"est_kind":"hdpe_liner","hdpe_thk":"1.5","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}},{"sku":"EST-HDPE-20","name":"HDPE geomembrane 2.0 mm, smooth (illustrative)","uom":"m2","description":"ILLUSTRATIVE placeholder cost, not a supplier's price. Import a rate sheet to replace it.","cost":28,"custom_data":{"est_kind":"hdpe_liner","hdpe_thk":"2.0","illustrative":true,"cost_source":"Illustrative placeholder","starter":"civil"}}]$items$::jsonb) as x(sku text, name text, uom text, description text, cost numeric, custom_data jsonb) loop
      if not exists (select 1 from products where tenant_id = t and sku = item.sku) then
        seq := seq + 1;
        insert into products (tenant_id, ref, name, sku, uom, description, cost_price, status, custom_data)
        values (t, 'PRD-' || lpad(seq::text, 4, '0'), item.name, item.sku, item.uom, item.description, item.cost, 'active', item.custom_data);
      end if;
    end loop;
  end if;

  raise notice 'Done for workspace %: the template and the catalogue items were added where missing; nothing existing was changed.', v_slug;
end
